style.css:
@-moz-document domain("discord.com") {
/* Fondo de pantalla con la imagen especificada */
  body {
    background: url("https://media.discordapp.net/attachments/e02d82d0-05c0-47f6-b82e-9b8009e7493f") no-repeat center center fixed;
    background-size: cover;
    color: #f0f8ff; /* Texto en blanco azulado para mejor contraste */
    font-family: 'Verdana', sans-serif;
    margin: 0;
    padding: 0;
  }

  /* Estilos para los contenedores y áreas principales */
  .container, .content, .main-content, .scroller {
    background-color: rgba(0, 128, 0, 0.85); /* Fondo verde oscuro semi-transparente */
    padding: 20px;
    border-radius: 12px;
    border: 2px solid #66cdaa; /* Borde en tono verde claro */
    box-shadow: 0 5px 10px rgba(0, 100, 0, 0.3); /* Sombra en verde oscuro */
    margin: 10px;
  }

  /* Estilo de encabezados */
  h1, h2, h3, h4, h5, h6 {
    color: #32cd32; /* Verde lima brillante para encabezados */
    font-weight: bold;
    text-transform: uppercase;
  }

  /* Enlaces */
  a {
    color: #00ced1; /* Color aguamarina para enlaces */
    text-decoration: none;
    font-weight: bold;
  }

  a:hover {
    color: #f0e68c; /* Color amarillo pálido en hover */
    text-decoration: underline;
  }

  /* Botones */
  button, .btn {
    background-color: #66cdaa; /* Verde claro para botones */
    color: #2f4f4f; /* Texto oscuro */
    border: none;
    padding: 12px 24px;
    border-radius: 8px;
    cursor: pointer;
    transition: background-color 0.3s ease, color 0.3s ease;
  }

  button:hover, .btn:hover {
    background-color: #3cb371; /* Verde mediano en hover */
    color: #ffffff; /* Texto blanco en hover */
  }
  
  /* Asegura que la caja del contenido ocupe el 100% de la pantalla */
  .app-3dGqvqA {
    min-height: 100vh; /* Ocupa el 100% de la altura de la pantalla */
  }
}
